import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Die meisten Kompressoren bieten feste Größen: 50 KB, 100 KB, 200 KB oder 500 KB. Aber was, wenn Ihr Portal 80 KB, 150 KB oder 1,5 MB verlangt?</p>\n<p>Das ist die Aufgabe des <a href=\"/de/bild-auf-zieldateigroesse-komprimieren/\">Zielgrößen-Kompressors</a>. Sie tippen jede Größe ein, die Sie brauchen, und das Tool komprimiert Ihr Bild so, dass es genau diese Zahl trifft.</p>\n<p>Diese Anleitung erklärt, wie angepasste Ziele funktionieren, wann man sie verwendet und wie man bei jeder Größe, die man wählt, die beste Qualität bekommt.</p>\n<h2 id=\"what-is-target-compression\">Was ist Komprimierung auf eine frei gewählte Dateigröße?</h2>\n<p>Die Zielkomprimierung lässt Sie die exakte Dateigröße benennen, die Sie wollen, in Kilobyte oder Megabyte. Das Tool arbeitet dann rückwärts, um eine Datei dieser Größe zu erzeugen.</p>\n<p>Sie tippen vielleicht 80 KB für ein Portal mit einer ungewöhnlichen Grenze oder 300 KB für ein Blog-Theme mit einem bestimmten Budget ein. Jede Zahl funktioniert.</p>\n<p>Das Tool nutzt dieselbe automatische Qualitätssuche wie die Tools mit fester Größe. Es testet Qualitätsstufen, bis es die höchste findet, die zu Ihrer Zahl passt.</p>\n<p>Wenn die Qualität allein das Ziel nicht erreichen kann, springt die intelligente Abmessungsskalierung ein. Das Tool verringert die Pixelgröße schrittweise, bis das Ziel erreicht ist.</p>\n<p>Das Ergebnis ist eine Datei, die knapp unter Ihrer gewählten Größe landet, mit der besten Qualität, die diese Größe halten kann.</p>\n<h2 id=\"how-it-works\">Wie das Tool funktioniert</h2>\n<p>Tippen Sie Ihre Zielgröße in das Eingabefeld ein und wählen Sie KB oder MB. Das Tool rechnet beim Wechsel automatisch zwischen den Einheiten um.</p>\n<p>Laden Sie Ihr Bild hoch. JPG-, PNG-, WebP- und HEIC-Dateien werden akzeptiert, mit Eingaben bis zu 25 MB.</p>\n<p>Das Tool führt seine Qualitätssuche zuerst in voller Auflösung aus. Erst wenn das scheitert, geht es die Abmessungen schrittweise nach unten.</p>\n<p>Eine Zusammenfassung zeigt das Ergebnis für jede Datei: das Ziel, die erreichte Größe und ob das Ziel getroffen oder verfehlt wurde.</p>\n<p>Der Stapelmodus komprimiert viele Bilder auf einmal auf dasselbe angepasste Ziel. Laden Sie sie gemeinsam als ZIP-Datei herunter, wenn der Stapel fertig ist.</p>\n<h2 id=\"kb-vs-mb\">KB vs. MB: Die richtige Einheit wählen</h2>\n<p>Kilobyte eignen sich für kleine Ziele. Portalgrenzen werden meist in KB angegeben, etwa 80 KB oder 150 KB – tippen Sie die Zahl also genau so ein, wie das Portal sie angibt.</p>\n<p>Megabyte eignen sich für größere Ziele. Ein Ziel von 1,5 MB oder 2 MB lässt sich in MB leichter tippen und lesen als 1536 KB oder 2048 KB.</p>\n<p>Der Wechsel der Einheiten rechnet die Zahl für Sie um. Wer 1 MB eintippt und zu KB wechselt, sieht 1024 KB – das Ziel bleibt identisch.</p>\n<p>Seien Sie vorsichtig mit der Rundung. Ein Portal, das 100 KB sagt, meint meist 102400 Byte, und das Tool misst in exakten Byte, um sicherzugehen.</p>\n<p>Im Zweifel tippen Sie die Zahl in der Einheit ein, die das Portal verwendet. Sich an die eigenen Worte des Portals zu halten, verhindert Umrechnungsfehler.</p>\n<h2 id=\"when-to-use-custom\">Wann man ein angepasstes Ziel verwendet</h2>\n<p>Ungewöhnliche Portalgrenzen sind der Hauptgrund. Ein Formular, das 80 KB oder 120 KB verlangt, kann von einem Tool mit fester Größe nicht bedient werden.</p>\n<p>Plattformbudgets sind ein weiterer Grund. Ein Blog-Theme oder eine App kann 300 KB pro Bild vorgeben, und ein angepasstes Ziel trifft es exakt.</p>\n<p>Testen ist ein dritter Grund. Dasselbe Bild auf 100 KB, 150 KB und 200 KB zu komprimieren, zeigt Ihnen genau, wo die Qualität aufhört, sich zu verbessern.</p>\n<p>Auch E-Mail-Anhänge profitieren. Ein Satz Bilder, der insgesamt unter 5 MB bleiben muss, lässt sich mit angepassten Zielen präzise abstimmen.</p>\n<p>Feste Tools decken die gängigen Größen ab. Das angepasste Tool deckt alles andere ab – was ein überraschend großer Teil der echten Arbeit ist.</p>\n<h2 id=\"binary-search-explained\">Die Qualitätssuche – einfach erklärt</h2>\n<p>Das Tool rät keine Qualitätszahl. Es sucht nach der besten und testet Qualitätsstufen, wobei es den Bereich jedes Mal eingrenzt.</p>\n<p>Stellen Sie es sich vor wie das Raten einer Zahl zwischen 1 und 100. Jeder Test halbiert den übrigen Bereich, es kommt also in einer Handvoll Schritten ans Ziel.</p>\n<p>Die Suche läuft zuerst in voller Auflösung. Das schützt Ihre Abmessungen, die den meisten Menschen wichtiger sind als ein kleiner Qualitätsunterschied.</p>\n<p>Erst wenn die Suche in voller Größe scheitert, beginnt die Skalierung. Das Tool testet dann kleinere Abmessungen und sucht bei jedem Schritt erneut nach der besten Qualität.</p>\n<p>Das Ergebnis ist die schärfste mögliche Version Ihres Bildes in genau der Größe, die Sie verlangt haben.</p>\n<h2 id=\"dimension-scaling\">Intelligente Abmessungsskalierung</h2>\n<p>Die Abmessungsskalierung verringert die Pixelgröße Ihres Bildes, wenn Qualitätsschnitte allein das Ziel nicht erreichen. Sie geschieht in kleinen Schritten, nicht in einem großen Sprung.</p>\n<p>Das Tool testet Skalen wie 90 Prozent, 80 Prozent und darunter und stoppt bei der ersten, die passt. Jeder Schritt behält so viel Größe wie möglich.</p>\n<p>Ein kleiner Skalierungsschritt ist meist unsichtbar. Ein Foto, das 800 Pixel breit angezeigt wird, sieht mit 720 Pixeln Breite identisch aus.</p>\n<p>Die Skalierung hilft am meisten bei sehr großen Originalen. Ein 4000 Pixel breites Foto hat weit mehr Pixel, als irgendein Bildschirm braucht – es zu beschneiden, kostet sichtbar nichts.</p>\n<p>Sie können die Abmessungen festlegen, wenn ein Portal exakte Pixel verlangt. Das Tool arbeitet dann härter allein an der Qualität und warnt Sie möglicherweise, wenn das Ziel nicht erreicht werden kann.</p>\n<h2 id=\"impossible-targets\">Wenn ein Ziel unmöglich ist</h2>\n<p>Manche Ziele lassen sich nicht erreichen. Ein Ziel von 2 KB für ein detailreiches Foto ist unmöglich, und das Tool sagt das ehrlich, statt Ihnen eine nutzlose Datei zu übergeben.</p>\n<p>Unmögliche Ziele kommen meist von einem Missverständnis. Ein Portal, das 2 MB verlangt, wurde vielleicht als 2 KB gelesen – tausendmal kleiner.</p>\n<p>Feste Abmessungen machen Ziele schwerer. Eine große Pixelgröße mit einer winzigen Dateigrenze kann wirklich unmöglich sein, und kein Tool kann das beheben.</p>\n<p>Verlustfreies PNG macht es am schwersten. Ein detailreiches Bild, das auf PNG festgelegt ist, passt vielleicht nie zu einem kleinen Ziel, egal wie stark man es verkleinert.</p>\n<p>Wenn das Tool eine verfehlte Zielmeldung gibt, ändern Sie, was Sie kontrollieren können. Wechseln Sie zu JPG, erlauben Sie die Skalierung oder schneiden Sie enger zu und lassen Sie es erneut laufen.</p>\n<h2 id=\"formats-custom\">Formate für angepasste Ziele</h2>\n<p>JPG ist das sicherste Format für angepasste Ziele. Es wird überall akzeptiert und komprimiert Fotos bei jeder Größe effizient.</p>\n<p>WebP schlägt JPG qualitativ oft leicht. Verwenden Sie es, wenn das Ziel es akzeptiert und Sie bei einem engen Ziel das schärfste Ergebnis brauchen.</p>\n<p>PNG eignet sich für Grafiken, nicht für Fotos. Ein Logo oder Diagramm bleibt in PNG pixelgenau, während ein Foto in PNG das Budget verschwendet.</p>\n<p>Die Option zur automatischen Umwandlung hilft hier. Wenn sie eingeschaltet ist, werden große PNG-Fotos während der Komprimierung automatisch in JPG oder WebP umgewandelt.</p>\n<p>Transparente Bilder verdienen eine Entscheidung. Behalten Sie Transparenz mit WebP, wenn möglich, oder flachen Sie auf JPG auf Weiß ab, wenn das Ziel es verlangt.</p>\n<h2 id=\"batch-custom\">Stapelkomprimierung auf ein angepasstes Ziel</h2>\n<p>Der Stapelmodus komprimiert viele Bilder auf einmal auf dasselbe angepasste Ziel. Legen Sie einen Ordner hinein, tippen Sie das Ziel ein und lassen Sie ihn laufen.</p>\n<p>Jedes Bild wird einzeln durchsucht. Ein einfaches Porträt und eine detailreiche Landschaft bekommen unterschiedliche Qualitätseinstellungen, auch wenn sie ein Ziel teilen.</p>\n<p>Die Zusammenfassung zeigt den Erfolg jeder Datei einzeln. Wenn drei Dateien das Ziel treffen und eine verfehlt, zeigt die Zusammenfassung genau, welche Aufmerksamkeit braucht.</p>\n<p>Laden Sie die Ergebnisse als ZIP-Datei herunter. Die Dateinamen kennzeichnen das angepasste Ziel, der Satz bleibt also organisiert.</p>\n<p>Stapel mit angepassten Zielen sind ideal für Portale mit ungewöhnlichen Grenzen. Fünfzig Bewerberfotos, alle auf 80 KB komprimiert, dauern Minuten, nicht Stunden.</p>\n<h2 id=\"common-mistakes\">Häufige Fehler bei angepassten Zielen</h2>\n<p>Die falsche Einheit einzutippen, ist der häufigste Fehler. Ein Ziel von 100 MB statt 100 KB erzeugt eine Datei, die tausendmal zu groß ist.</p>\n<p>Ein unmögliches Ziel festzulegen, verschwendet Zeit. Ein Ziel von 3 KB für ein Foto wird immer verfehlt, und das Tool wird es Ihnen sagen.</p>\n<p>Auch das Ergebnis nicht zu prüfen, kommt häufig vor. Die Dateigröße mag stimmen, während das Bild verschwommen ist – sehen Sie es sich also vor dem Herunterladen an.</p>\n<p>Eine bereits komprimierte Datei erneut zu komprimieren, fügt Schaden hinzu. Beginnen Sie immer vom Original, selbst wenn das Ziel großzügig ist.</p>\n<p>Und gehen Sie schließlich nicht davon aus, dass jedes Portal WebP akzeptiert. Prüfen Sie zuerst die akzeptierten Formate, sonst komprimieren Sie vielleicht zweimal.</p>\n<h2 id=\"privacy-custom\">Datenschutz bei angepassten Zielen</h2>\n<p>Die gesamte Komprimierung findet in Ihrem Browser statt. Ihre Fotos werden lokal verarbeitet und nie auf einen Server hochgeladen.</p>\n<p>Das ist wichtig bei angepassten Zielen, die oft sensible Dokumente wie Verträge, medizinische Scans und Kundenfreigaben bedienen.</p>\n<p>Kamera-GPS-Tags und EXIF-Daten werden während der Komprimierung entfernt. Die heruntergeladenen Dateien enthalten keinen Hinweis darauf, wo oder wann sie aufgenommen wurden.</p>\n<p>Für sensible Arbeiten ist dieser Datenschutz ein Merkmal. Sie können einen vertraulichen Stapel komprimieren, ohne sich Sorgen zu machen, wer ihn sonst noch sehen könnte.</p>\n<p>Prüfen Sie die heruntergeladenen Dateien vor dem Teilen immer noch einmal. Datenschutz bei der Verarbeitung ersetzt keine Sorgfalt bei der Verteilung.</p>\n<h2 id=\"unit-mistakes\">Einheitenfehler und wie man sie vermeidet</h2>\n<p>Der teuerste Fehler bei der angepassten Komprimierung ist ein Einheitenfehler. Wer 100 MB eintippt, wenn er 100 KB meinte, erzeugt ein Ziel, das tausendmal zu groß ist.</p>\n<p>Lesen Sie die Portalgrenze immer zweimal. Notieren Sie die Zahl und die Einheit getrennt und tippen Sie sie dann getrennt ins Tool ein.</p>\n<p>Lesen Sie die Eingabe nach dem Tippen noch einmal zurück, bevor Sie hochladen. Ein kurzer Blick entdeckt ein fehlendes Komma oder eine zusätzliche Null.</p>\n<p>Denken Sie daran, dass 1 MB 1024 KB entspricht, nicht 1000 KB. Das Tool rechnet mit 1024 KB pro MB, so wie Betriebssysteme Dateien messen.</p>\n<p>Wenn ein Ergebnis wild falsch aussieht, prüfen Sie zuerst die Einheit. In neun von zehn Fällen ist die Einheit das Problem, nicht das Tool.</p>\n<h2 id=\"target-for-email\">Angepasste Ziele für E-Mail-Anhänge</h2>\n<p>E-Mail-Systeme begrenzen Anhänge, oft auf 20 MB oder 25 MB pro Nachricht. Ein Satz Bilder, der in diese Grenze passen muss, profitiert von angepassten Zielen.</p>\n<p>Teilen Sie die Grenze durch die Anzahl der Bilder, um das Budget jeder Datei zu finden. Zehn Bilder, die sich eine 20-MB-Grenze teilen, bekommen jeweils 2 MB.</p>\n<p>Verwenden Sie ein etwas kleineres Ziel als die exakte Aufteilung. Ein Sicherheitsspielraum deckt Rundungen ab und hält die Summe sicher unter der Grenze.</p>\n<p>Komprimieren Sie den Stapel auf das angepasste Ziel und prüfen Sie die Gesamtgröße der ZIP-Datei. Wenn sie die Grenze überschreitet, senken Sie das Ziel und lassen Sie ihn erneut laufen.</p>\n<p>Bei einem einzelnen Bild spielt die Grenze selten eine Rolle. Ein Foto mit 500 KB versendet sich problemlos, während eines mit 5 MB vielleicht zurückkommt.</p>\n<h2 id=\"target-for-print-prep\">Bilder für den Druck mit angepassten Zielen vorbereiten</h2>\n<p>Druckereien geben manchmal eine maximale Dateigröße für Uploads an. Ein angepasstes Ziel trifft diese Zahl exakt, ohne zu raten.</p>\n<p>Denken Sie daran, dass Druck Auflösung braucht, nicht nur Dateigröße. Eine 2-MB-Datei mit niedriger Auflösung druckt trotzdem schlecht, egal wie groß sie ist.</p>\n<p>Halten Sie die Abmessungen hoch, wenn Sie für den Druck vorbereiten. Lassen Sie das Tool allein an der Qualität arbeiten und erlauben Sie die Skalierung nur, wenn das Ziel es verlangt.</p>\n<p>Prüfen Sie den gedruckten Korrekturabzug, wenn Sie können. Eine Bildschirmvorschau verbirgt Probleme, die Papier aufdeckt – besonders Bänder in glatten Flächen.</p>\n<p>Für die endgültige Drucklieferung schicken Sie das Original, wenn die Druckerei es akzeptiert. Das angepasste Ziel ist für Upload-Grenzen gedacht, nicht für die Druckmaschine selbst.</p>\n<h2 id=\"comparing-targets\">Mehrere Ziele an einem Bild vergleichen</h2>\n<p>Dasselbe Bild mit mehreren Zielen laufen zu lassen, zeigt Ihnen, wo die Qualität aufhört, sich zu verbessern. Komprimieren Sie es auf 100 KB, 200 KB und 500 KB und vergleichen Sie.</p>\n<p>Betrachten Sie alle drei in voller Größe. Der Sprung von 100 KB auf 200 KB ist meist sichtbar, während der Sprung von 200 KB auf 500 KB oft nicht sichtbar ist.</p>\n<p>Dieser Vergleich sagt Ihnen die kleinste Größe, die gut aussieht. Sie zu verwenden, spart Bandbreite bei jedem künftigen Bild derselben Art.</p>\n<p>Behalten Sie die Vergleichsdateien als Referenz. Sie werden Ihre Anleitung für die Zielwahl bei ähnlichen Bildern später.</p>\n<p>Testen dauert Minuten und zahlt sich monatelang aus. Ein getestetes Ziel schlägt jedes Mal ein geratenes Ziel.</p>\n<h2 id=\"saving-presets\">Ihre gängigen Ziele speichern</h2>\n<p>Die meisten Menschen verwenden immer wieder dieselben wenigen Ziele. Ein Portal, das diesen Monat 80 KB will, will nächsten Monat auch 80 KB.</p>\n<p>Führen Sie eine kurze Liste Ihrer gängigen Ziele mit ihren Zwecken. Eine Notiz wie „Prüfungsportal 80 KB, Blog-Titelbild 300 KB“ erspart das erneute Lesen von Regeln.</p>\n<p>Setzen Sie ein Lesezeichen auf das Tool mit dem Ziel im Kopf. Das Tool merkt sich zwischen Besuchen nichts, Ihre Liste ist also das Gedächtnis.</p>\n<p>Teilen Sie die Liste mit Ihrem Team. Eine gemeinsame Zielliste verhindert, dass jede Person anders rät.</p>\n<p>Prüfen Sie die Liste, wenn sich Regeln ändern. Portale aktualisieren ihre Grenzen, und ein altes Ziel kann zu einem abgelehnten Upload werden.</p>\n<h2 id=\"accessibility-custom\">Barrierefreiheit bei angepassten Zielen</h2>\n<p>Ein komprimiertes Bild muss trotzdem jedem Betrachter dienen. Ein enges angepasstes Ziel, das Text verwischt, lässt Leser im Stich, die diesen Text brauchen.</p>\n<p>Prüfen Sie Kontrast und Lesbarkeit nach der Komprimierung. Textüberlagerungen und kleine Beschriftungen müssen bei dem Ziel, das Sie gewählt haben, lesbar bleiben.</p>\n<p>Fügen Sie Bildern, die fürs Web komprimiert wurden, immer Alt-Text hinzu. Eine kleine Datei mit gutem Alt-Text dient mehr Menschen als eine perfekte Datei ohne Alt-Text.</p>\n<p>Wenn Text wichtig ist, bevorzugen Sie ein größeres Ziel. Die zusätzlichen Kilobyte schützen die Lesbarkeit, was mehr wert ist als eine kleinere Datei.</p>\n<p>Komprimierung und Barrierefreiheit gehören zusammen. Eine klare, kontrastreiche Quelle komprimiert sich besser und ist für jeden Betrachter leichter zu lesen.</p>\n<p>Die praktischen Schritte finden Sie unter <a href=\"/de/blog/bild-auf-genaue-kb-groesse-komprimieren-anleitung/\">Bild auf eine genaue KB-Größe komprimieren: Anleitung</a>. Die ausführliche Erklärung der Suche finden Sie unter <a href=\"/de/blog/exakte-kb-groesse-qualitaetssuche-erklaert/\">Exakte KB-Größe treffen: So funktioniert die Qualitätssuche</a>. Wenn Ihnen eine feste Größe passt, decken der <a href=\"/de/bild-auf-100-kb-komprimieren/\">100-KB-Kompressor</a> und der <a href=\"/de/bild-auf-200-kb-komprimieren/\">200-KB-Kompressor</a> die gängigen Grenzen ab.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Welchen Größenbereich kann ich in den Zielkompressor eintippen?","answer":"Sie können jede angepasste Größe in KB oder MB eintippen, von wenigen Kilobyte bis zu mehreren Megabyte. Sehr kleine Ziele wie 2 KB oder 3 KB werden bei detailreichen Fotos meist verfehlt, und das Tool sagt Ihnen ehrlich, wenn ein Ziel nicht erreicht werden kann."},{"question":"Wie genau ist die endgültige Dateigröße im Vergleich zu meinem Ziel?","answer":"Sehr genau. Das Tool zielt in exakten Byte knapp unter Ihr Ziel und landet meist innerhalb weniger Kilobyte davon. Der kleine Sicherheitsspielraum schützt Sie vor Byte-Rundungsunterschieden zwischen Systemen."},{"question":"Kann ich einen Stapel Fotos auf dieselbe angepasste Größe komprimieren?","answer":"Ja. Fügen Sie mehrere Bilder hinzu, jedes wird auf dasselbe angepasste Ziel komprimiert, und laden Sie sie dann gemeinsam als ZIP herunter. Die Zusammenfassung zeigt, welche Dateien das Ziel getroffen und welche es verfehlt haben, damit Sie die Fehlschläge einzeln beheben können."},{"question":"Was passiert, wenn ich ein Bild hochlade, das bereits kleiner ist als mein Ziel?","answer":"Das Tool warnt Sie, dass die Datei wachsen würde, wenn sie erneut komprimiert wird. Eine Datei, die kleiner ist als Ihr Ziel, ist bereits in Ordnung – verwenden Sie sie, wie sie ist, statt sie gewaltsam durch die Komprimierung zu zwingen und Schaden hinzuzufügen."},{"question":"Warum testet das Tool zuerst die Qualität, bevor es die Abmessungen verkleinert?","answer":"Qualitätsschnitte bewahren die Pixelzahl, was den meisten Menschen wichtiger ist als ein kleiner Qualitätsunterschied. Die Abmessungsskalierung beginnt erst, wenn die Qualität allein das Ziel nicht erreichen kann. Diese Reihenfolge hält Ihre Bilder so groß und so scharf wie möglich."},{"question":"Ist es besser, ein festes Tool oder das Tool für angepasste Ziele zu verwenden?","answer":"Verwenden Sie ein festes Tool, wenn seine Größe zu Ihrem Bedarf passt, denn es ist einen Klick schneller. Verwenden Sie das angepasste Tool, wenn das Portal oder die Plattform eine ungewöhnliche Größe verlangt oder wenn Sie mehrere Größen testen wollen, um das beste Gleichgewicht für Ihre Bilder zu finden."}];
